/* Minimal PDF writer: one JPEG per page, embedded as DCTDecode (no re-encoding,
   no external library). Pages are A4 with the image fitted inside a margin. */
function buildPdfFromJpegs(images, title) {
  // images: [{ bin: binaryString, w, h, caption }]
  const A4W = 595.28, A4H = 841.89, M = 24;
  const enc = s => s;
  let objs = [], out = '';

  const add = body => { objs.push(body); return objs.length; };  // returns obj number

  // Reserve fixed object numbers: 1 catalog, 2 pages, 3 font.
  const FONT_NO = 3;
  objs.push(null, null, null);

  const kids = [];
  images.forEach(img => {
    const scale = Math.min((A4W - 2 * M) / img.w, (A4H - 2 * M - 26) / img.h);
    const dw = img.w * scale, dh = img.h * scale;
    const dx = (A4W - dw) / 2, dy = (A4H - dh) / 2 - 6;

    const imgNo = add(
      '<< /Type /XObject /Subtype /Image /Width ' + img.w + ' /Height ' + img.h +
      ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' +
      img.bin.length + ' >>\nstream\n' + img.bin + '\nendstream');

    let stream = 'q\n' + dw.toFixed(2) + ' 0 0 ' + dh.toFixed(2) + ' ' +
                 dx.toFixed(2) + ' ' + dy.toFixed(2) + ' cm\n/I0 Do\nQ\n';
    if (img.caption) {
      stream += 'BT /F1 9 Tf ' + M.toFixed(2) + ' ' + (A4H - M + 4).toFixed(2) +
                ' Td (' + String(img.caption).replace(/[\\()]/g, '\\$&') + ') Tj ET\n';
    }
    const contNo = add('<< /Length ' + stream.length + ' >>\nstream\n' + stream + '\nendstream');

    const pageNo = add(
      '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + A4W + ' ' + A4H + ']' +
      ' /Resources << /XObject << /I0 ' + imgNo + ' 0 R >>' +
      ' /Font << /F1 ' + FONT_NO + ' 0 R >> >>' +
      ' /Contents ' + contNo + ' 0 R >>');
    kids.push(pageNo);
  });

  objs[2] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';

  objs[0] = '<< /Type /Catalog /Pages 2 0 R >>';
  objs[1] = '<< /Type /Pages /Count ' + kids.length + ' /Kids [' +
            kids.map(k => k + ' 0 R').join(' ') + '] >>';

  out = '%PDF-1.4\n';
  const offsets = [];
  objs.forEach((body, i) => {
    offsets.push(out.length);
    out += (i + 1) + ' 0 obj\n' + body + '\nendobj\n';
  });
  const xref = out.length;
  out += 'xref\n0 ' + (objs.length + 1) + '\n0000000000 65535 f \n';
  offsets.forEach(o => { out += String(o).padStart(10, '0') + ' 00000 n \n'; });
  out += 'trailer\n<< /Size ' + (objs.length + 1) + ' /Root 1 0 R >>\nstartxref\n' +
         xref + '\n%%EOF';
  return out;
}
